package com.pirris.mapper;

import java.util.List;

import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;

import com.pirris.dto.lessonpackage.LessonPackageDto;
import com.pirris.model.LessonPackageModel;

/**
 * Compile-time mapper from {@link LessonPackageModel} to the Pacchetti view
 * DTOs. Generated by MapStruct as a CDI bean.
 *
 * <p>The credit counters are derived, not stored: the mapper fills them with
 * neutral values until the package accounting exists.</p>
 */
@Mapper(componentModel = MappingConstants.ComponentModel.CDI)
public interface LessonPackageMapper {

    // ---- entity -> DTO (reads) ----

    // TODO(Phase 3): derived by PackageService = capacity − participants with this
    // package whose session is completed.
    @Mapping(target = "usedCredits", constant = "0")
    @Mapping(target = "remainingCredits", constant = "0")
    LessonPackageDto toDto(LessonPackageModel lessonPackage);

    List<LessonPackageDto> toDtos(List<LessonPackageModel> lessonPackages);
}
